class User:
    def __init__(self, name, email):
        self.name = name
        self.email = email

    @classmethod
    def from_csv(cls, line):
        name, email = line.split(",")
        return cls(name.strip(), email.strip())

    @classmethod
    def from_dict(cls, data):
        return cls(data["name"], data["email"])

    @staticmethod
    def is_valid_email(email):
        return "@" in email and "." in email.split("@")[-1]

    def __repr__(self):
        return f"User({self.name!r}, {self.email!r})"


print(User.from_csv("Riya Sharma, riya@example.in"))
print(User.from_dict({"name": "Arjun", "email": "arjun@mail.com"}))
print(User.is_valid_email("kabir@site"), User.is_valid_email("kabir@site.in"))

